1: import { Injectable } from '@angular/core';
2: import { HttpClient, HttpHeaders } from '@angular/common/http';
3: import { environment } from '../../environments/environment';
4: import { catchError } from 'rxjs/operators';
5: import { HttpErrorManager } from './errorManager'
6: import { Observable } from 'rxjs';
7: 
8: /**
9:  * This class manage the http connections with internal REST services. Use the response format {
10:  *  Code: 'xxxxx',
11:  *  Body: 'Some Data' (this element is returned if the request is success)
12:  *  ...
13:  * }
14:  */
15: @Injectable({
16:   providedIn: 'root',
17: })
18: export class RequestManager {
19:   private path!: any;
20:   public httpOptions?: { headers: HttpHeaders };
21:   constructor(private http: HttpClient, private errManager: HttpErrorManager) {
22:     const acces_token = window.localStorage.getItem('access_token');
23:     if (acces_token !== null) {
24:       this.httpOptions = {
25:          headers: new HttpHeaders({
26:            'Content-Type': 'application/json',
27:            'Authorization': `Bearer ${acces_token}`,
28:          }),
29:       }
30:     }
31:   }
32: 
33: 
34:   /**
35:    * Use for set the source path of the service (service's name must be present at src/environment/environment.ts)
36:    * @param service: string
37:    */
38:   public setPath(service: string) {
39:     this.path = environment[service as keyof typeof environment];
40:   }
41: 
42: 
43:   /**
44:    * Perform a GET http request
45:    * @param endpoint service's end-point
46:    * @param params (an Key, Value object with que query params for the request)
47:    * @returns Observable<any>
48:    */
49:   get<T = any>(endpoint: any): Observable<T> {
50:     return this.http.get<T>(`${this.path}${endpoint}`, this.httpOptions).pipe(
51:       catchError(this.errManager.handleError.bind(this)),
52:     );
53:   }
54: 
55:   /**
56:    * Perform a POST http request
57:    * @param endpoint service's end-point
58:    * @param element data to send as JSON
59:    * @returns Observable<any>
60:    */
61:   post(endpoint: any, element: any) {
62:     return this.http.post<any>(`${this.path}${endpoint}`, element, this.httpOptions).pipe(
63:       catchError(this.errManager.handleError),
64:     );
65:   }
66: 
67:   /**
68:    * Perform a POST http request
69:    * @param endpoint service's end-point
70:    * @param element data to send as JSON
71:    * @returns Observable<any>
72:    */
73:   post_file(endpoint: any, element: any) {
74:     return this.http.post<any>(`${this.path}${endpoint}`, element, {    headers: new HttpHeaders({
75:       'Content-Type': 'multipart/form-data',
76:   })}).pipe(
77:       catchError(this.errManager.handleError),
78:     );
79:   }
80: 
81:   /**
82:    * Perform a PUT http request
83:    * @param endpoint service's end-point
84:    * @param element data to send as JSON, With the id to UPDATE
85:    * @returns Observable<any>
86:    */
87:   put(endpoint: any, element: { Id: any; }) {
88:     const path = (element.Id) ? `${this.path}${endpoint}/${element.Id}` : `${this.path}${endpoint}`;
89:     return this.http.put<any>(path, element, this.httpOptions).pipe(
90:       catchError(this.errManager.handleError),
91:     );
92:   }
93: 
94:   /**
95:    * Perform a DELETE http request
96:    * @param endpoint service's end-point
97:    * @param id element's id for remove
98:    * @returns Observable<any>
99:    */
100:   delete(endpoint: any, id: any) {
101:     return this.http.delete<any>(`${this.path}${endpoint}/${id}`, this.httpOptions).pipe(
102:       catchError(this.errManager.handleError),
103:     );
104:   }
105: };

