14:     canActivate(route: ActivatedRouteSnapshot, state: RouterStateSnapshot) {
15:         const menuInfo = localStorage.getItem('menu');
16:         const menuPermisos = menuInfo ? JSON.parse(atob(menuInfo)) : null;
17:         const fullUrl = window.location.href;
18:         const url = new URL(fullUrl);
19:         const path = url.pathname;
20: 
21:         // Obtener parámetros de la ruta
22:         const params = route.params;
23: 
24:         if (menuPermisos != null) {
25:             // Pasar tanto la URL como los parámetros a la función de verificación
26:             if (checkUrlExists(menuPermisos, path, params)) {
27:                 return true;
28:             }
29:         }
30: 
31:         // this.AlertService.showErrorAlert('Error de acceso');
32:         return false;
33:     }
