40: // Recorrer el menú para verificar si la URL y los parámetros existen
41: function checkUrlExists(menuItems: any, targetUrl: string, params: any) {
42:     return menuItems.some((item: any) => {
43:         // Verificar la URL y los parámetros
44:         if (item.Url === targetUrl && checkParams(item.Params, params)) {
45:             return true;
46:         }
47:         if (item.Opciones && item.Opciones.length > 0) {
48:             return checkUrlExists(item.Opciones, targetUrl, params);
49:         }
50:         return false;
51:     });
52: }
53: 
54: // Verificar los parámetros de la ruta
55: function checkParams(expectedParams: any, actualParams: any): boolean {
56:     if (!expectedParams) {
57:         return true; // No se requieren parámetros específicos
58:     }
59:     for (let key in expectedParams) {
60:         if (expectedParams[key] !== actualParams[key]) {
61:             return false; // Un parámetro no coincide
62:         }
63:     }
64:     return true; // Todos los parámetros coinciden
65: }

